## What Is Context?

Context provides a way to **share data globally** across your component tree **without passing props manually through every level**.

Perfect for: theme (light/dark), authenticated user, language, shopping cart, notifications.

---

## Creating and Using Context — 3 Steps

```jsx
// Step 1: Create the context
import { createContext } from 'react'

const ThemeContext = createContext(null)
// null is the default value if no Provider is above in the tree
```

```jsx
// Step 2: Create a Provider component that wraps your app
import { useState } from 'react'

function ThemeProvider({ children }) {
  const [theme, setTheme] = useState('light')

  function toggleTheme() {
    setTheme(prev => prev === 'light' ? 'dark' : 'light')
  }

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  )
}
```

```jsx
// Step 3: Consume context in any component with useContext
import { useContext } from 'react'

function ThemeToggleButton() {
  const { theme, toggleTheme } = useContext(ThemeContext)

  return (
    <button onClick={toggleTheme}>
      Switch to {theme === 'light' ? 'Dark' : 'Light'} Mode
    </button>
  )
}

function App() {
  const { theme } = useContext(ThemeContext)

  return (
    <div style={{
      background: theme === 'light' ? '#ffffff' : '#0f172a',
      color: theme === 'light' ? '#0f172a' : '#ffffff',
      minHeight: '100vh',
      padding: '20px',
    }}>
      <h1>My App ({theme} mode)</h1>
      <ThemeToggleButton />
    </div>
  )
}
```

```jsx
// Wrap your app in the provider (in main.jsx or App.jsx)
ReactDOM.createRoot(document.getElementById('root')).render(
  <ThemeProvider>
    <App />
  </ThemeProvider>
)
```

---

## Custom Hook Pattern — Best Practice

Instead of importing both `ThemeContext` and `useContext` everywhere, create a custom hook:

```jsx
// context/ThemeContext.jsx — All context logic in one file
import { createContext, useContext, useState } from 'react'

const ThemeContext = createContext(null)

export function ThemeProvider({ children }) {
  const [theme, setTheme] = useState('light')
  const toggleTheme = () => setTheme(t => t === 'light' ? 'dark' : 'light')

  return (
    <ThemeContext.Provider value={{ theme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  )
}

// Custom hook — much cleaner to use!
export function useTheme() {
  const context = useContext(ThemeContext)
  if (!context) throw new Error('useTheme must be used inside ThemeProvider')
  return context
}
```

```jsx
// Now any component just imports useTheme — clean and simple!
import { useTheme } from '../context/ThemeContext'

function Header() {
  const { theme, toggleTheme } = useTheme()
  return (
    <header>
      <h1>My App</h1>
      <button onClick={toggleTheme}>{theme === 'light' ? '🌙' : '☀️'}</button>
    </header>
  )
}
```

---

## Real Example: Auth Context

```jsx
// context/AuthContext.jsx
import { createContext, useContext, useState } from 'react'

const AuthContext = createContext(null)

export function AuthProvider({ children }) {
  const [user, setUser] = useState(null)

  async function login(email, password) {
    // Call your API here
    const response = await fetch('/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
    })
    const data = await response.json()
    if (data.success) {
      setUser(data.user)
    }
    return data
  }

  function logout() {
    setUser(null)
  }

  return (
    <AuthContext.Provider value={{ user, login, logout, isLoggedIn: !!user }}>
      {children}
    </AuthContext.Provider>
  )
}

export const useAuth = () => useContext(AuthContext)
```

```jsx
// Using auth context anywhere in the app
import { useAuth } from '../context/AuthContext'

function Navbar() {
  const { user, logout, isLoggedIn } = useAuth()

  return (
    <nav>
      {isLoggedIn ? (
        <>
          <span>Welcome, {user.name}!</span>
          <button onClick={logout}>Logout</button>
        </>
      ) : (
        <a href="/login">Login</a>
      )}
    </nav>
  )
}
```

