## Fetch on User Action (Not on Mount)

```jsx
// Fetch when the user does something — not on initial render
import { useState } from 'react'

function GitHubUser() {
  const [username, setUsername] = useState('')
  const [user, setUser] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)

  async function handleSearch(e) {
    e.preventDefault()
    if (!username.trim()) return

    setLoading(true)
    setError(null)
    setUser(null)

    try {
      const res = await fetch('https://api.github.com/users/' + username)
      if (!res.ok) throw new Error('User "' + username + '" not found')
      const data = await res.json()
      setUser(data)
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  return (
    <div>
      <form onSubmit={handleSearch}>
        <input
          value={username}
          onChange={e => setUsername(e.target.value)}
          placeholder="Enter GitHub username..."
        />
        <button type="submit" disabled={loading}>
          {loading ? 'Searching...' : 'Search'}
        </button>
      </form>

      {error && <p style={{ color: 'red' }}>{error}</p>}

      {user && (
        <div style={{ marginTop: '20px' }}>
          <img src={user.avatar_url} alt={user.login} style={{ width: '80px', borderRadius: '50%' }} />
          <h2>{user.name}</h2>
          <p>{user.bio}</p>
          <p>Followers: {user.followers} | Repos: {user.public_repos}</p>
        </div>
      )}
    </div>
  )
}
