## Fetching with Axios

Axios is a popular alternative to fetch that handles JSON parsing and error status codes automatically:

```bash
npm install axios
```

```jsx
// Using axios — cleaner than fetch for most use cases
import axios from 'axios'
import { useState, useEffect } from 'react'

function UsersPage() {
  const [users, setUsers] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    async function fetchUsers() {
      try {
        // axios automatically parses JSON and throws on non-2xx status
        const { data } = await axios.get('https://jsonplaceholder.typicode.com/users')
        setUsers(data)
      } catch (err) {
        // axios puts the error message in err.response?.data?.message
        setError(err.response?.data?.message || err.message)
      } finally {
        setLoading(false)
      }
    }

    fetchUsers()
  }, [])

  if (loading) return <p>Loading...</p>
  if (error) return <p>Error: {error}</p>

  return (
    <ul>
      {users.map(u => <li key={u.id}>{u.name} — {u.email}</li>)}
    </ul>
  )
}
```

