## Refetch on Demand (Retry Button)

```jsx
// Add a refetch trigger using a counter in the dependency array
import { useState, useEffect } from 'react'

function DataWithRetry() {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [retryCount, setRetryCount] = useState(0)

  useEffect(() => {
    setLoading(true)
    setError(null)

    fetch('/api/data')
      .then(res => res.json())
      .then(d => { setData(d); setLoading(false) })
      .catch(err => { setError(err.message); setLoading(false) })
  }, [retryCount])  // ← Re-run every time retryCount changes

  return (
    <div>
      {loading && <p>Loading...</p>}
      {error && (
        <div>
          <p>Error: {error}</p>
          <button onClick={() => setRetryCount(c => c + 1)}>Retry</button>
        </div>
      )}
      {data && <pre>{JSON.stringify(data, null, 2)}</pre>}
    </div>
  )
}
```

---

## Chapter Summary

- Always handle three states: **loading**, **success**, and **error**
- Use **async/await** inside a named function inside `useEffect` (you can't make the callback itself async)
- `fetch` requires manual JSON parsing and doesn't throw on 4xx/5xx — check `response.ok`
- **axios** auto-parses JSON and throws on non-2xx status — cleaner for most cases
- Cancel in-flight requests with **AbortController** to prevent memory leaks on unmount

## Controlled vs Uncontrolled Inputs

In React, there are two ways to handle form inputs:

```text
Controlled   → React state controls the input value (recommended)
Uncontrolled → The DOM controls the value (accessed with useRef)
```

Always prefer **controlled** inputs — they give you instant access to values and make validation easy.

---

## Controlled Inputs — Every Input Type

```jsx
// Handling different input types with controlled state
import { useState } from 'react'

function AllInputTypesDemo() {
  const [form, setForm] = useState({
    name: '',
    email: '',
    password: '',
    age: '',
    bio: '',
    gender: '',
    skills: [],
    agreed: false,
  })

  function update(field, value) {
    setForm(prev => ({ ...prev, [field]: value }))
  }

  function handleCheckboxGroup(value, checked) {
    setForm(prev => ({
      ...prev,
      skills: checked
        ? [...prev.skills, value]
        : prev.skills.filter(s => s !== value),
    }))
  }

  return (
    <form>
      {/* Text input */}
      <input type="text" value={form.name}
        onChange={e => update('name', e.target.value)} placeholder="Name" />

      {/* Email */}
      <input type="email" value={form.email}
        onChange={e => update('email', e.target.value)} placeholder="Email" />

      {/* Password */}
      <input type="password" value={form.password}
        onChange={e => update('password', e.target.value)} placeholder="Password" />

      {/* Number */}
      <input type="number" value={form.age}
        onChange={e => update('age', e.target.value)} placeholder="Age" />

      {/* Textarea */}
      <textarea value={form.bio}
        onChange={e => update('bio', e.target.value)} placeholder="Bio" />

      {/* Select */}
      <select value={form.gender} onChange={e => update('gender', e.target.value)}>
        <option value="">Select gender...</option>
        <option value="male">Male</option>
        <option value="female">Female</option>
        <option value="other">Other</option>
      </select>

      {/* Checkbox group */}
      {['React', 'Node.js', 'CSS'].map(skill => (
        <label key={skill}>
          <input
            type="checkbox"
            checked={form.skills.includes(skill)}
            onChange={e => handleCheckboxGroup(skill, e.target.checked)}
          />
          {skill}
        </label>
      ))}

      {/* Single checkbox */}
      <label>
        <input
          type="checkbox"
          checked={form.agreed}
          onChange={e => update('agreed', e.target.checked)}
        />
        I agree to the terms
      </label>
    </form>
  )
}
