## Form Validation on Submit

```jsx
// Client-side validation with error messages
import { useState } from 'react'

function RegistrationForm() {
  const [form, setForm] = useState({ name: '', email: '', password: '', confirmPassword: '' })
  const [errors, setErrors] = useState({})
  const [submitted, setSubmitted] = useState(false)

  function validate() {
    const newErrors = {}

    if (!form.name.trim()) {
      newErrors.name = 'Name is required'
    } else if (form.name.trim().length < 2) {
      newErrors.name = 'Name must be at least 2 characters'
    }

    const emailRegex = /^[^s@]+@[^s@]+.[^s@]+$/
    if (!form.email) {
      newErrors.email = 'Email is required'
    } else if (!emailRegex.test(form.email)) {
      newErrors.email = 'Enter a valid email address'
    }

    if (!form.password) {
      newErrors.password = 'Password is required'
    } else if (form.password.length < 8) {
      newErrors.password = 'Password must be at least 8 characters'
    }

    if (!form.confirmPassword) {
      newErrors.confirmPassword = 'Please confirm your password'
    } else if (form.password !== form.confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match'
    }

    return newErrors
  }

  function handleSubmit(e) {
    e.preventDefault()

    const validationErrors = validate()

    if (Object.keys(validationErrors).length > 0) {
      setErrors(validationErrors)   // Show errors
      return
    }

    // No errors — submit!
    setErrors({})
    setSubmitted(true)
    console.log('Submitting:', form)
  }

  function update(field, value) {
    setForm(prev => ({ ...prev, [field]: value }))
    // Clear error for this field as user types
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }))
    }
  }

  if (submitted) {
    return <div style={{ color: 'green' }}>Account created! Welcome, {form.name}!</div>
  }

  return (
    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '16px', maxWidth: '400px' }}>
      <h2>Create Account</h2>

      <div>
        <input
          value={form.name}
          onChange={e => update('name', e.target.value)}
          placeholder="Full Name"
          style={{ borderColor: errors.name ? 'red' : '#ccc' }}
        />
        {errors.name && <p style={{ color: 'red', fontSize: '12px', margin: '4px 0 0' }}>{errors.name}</p>}
      </div>

      <div>
        <input
          type="email"
          value={form.email}
          onChange={e => update('email', e.target.value)}
          placeholder="Email"
          style={{ borderColor: errors.email ? 'red' : '#ccc' }}
        />
        {errors.email && <p style={{ color: 'red', fontSize: '12px', margin: '4px 0 0' }}>{errors.email}</p>}
      </div>

      <div>
        <input
          type="password"
          value={form.password}
          onChange={e => update('password', e.target.value)}
          placeholder="Password (min 8 chars)"
          style={{ borderColor: errors.password ? 'red' : '#ccc' }}
        />
        {errors.password && <p style={{ color: 'red', fontSize: '12px', margin: '4px 0 0' }}>{errors.password}</p>}
      </div>

      <div>
        <input
          type="password"
          value={form.confirmPassword}
          onChange={e => update('confirmPassword', e.target.value)}
          placeholder="Confirm Password"
          style={{ borderColor: errors.confirmPassword ? 'red' : '#ccc' }}
        />
        {errors.confirmPassword && <p style={{ color: 'red', fontSize: '12px', margin: '4px 0 0' }}>{errors.confirmPassword}</p>}
      </div>

      <button type="submit">Create Account</button>
    </form>
  )
}
```

