## What Is a Custom Hook?

A custom hook is a **JavaScript function that starts with "use"** and calls other hooks inside it. It lets you extract stateful logic into a reusable function.

```text
Problem: The same useEffect + useState pattern repeated in 5 components
Solution: Extract that logic into a custom hook — call it once from any component
```

---

## Your First Custom Hook: useFetch

```jsx
// Without custom hook — fetch logic repeated everywhere
function ComponentA() {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    fetch('/api/users').then(r => r.json()).then(setData).catch(setError).finally(() => setLoading(false))
  }, [])

  // ... same code in ComponentB, ComponentC, ComponentD 😩
}
```

```jsx
// ✅ With custom hook — write the logic ONCE, reuse everywhere
import { useState, useEffect } from 'react'

// hooks/useFetch.js
function useFetch(url) {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)

  useEffect(() => {
    let cancelled = false

    async function fetchData() {
      try {
        setLoading(true)
        setError(null)
        const res = await fetch(url)
        if (!res.ok) throw new Error('HTTP error: ' + res.status)
        const json = await res.json()
        if (!cancelled) setData(json)
      } catch (err) {
        if (!cancelled) setError(err.message)
      } finally {
        if (!cancelled) setLoading(false)
      }
    }

    fetchData()

    return () => { cancelled = true }  // Cleanup on unmount
  }, [url])  // Refetch when URL changes

  return { data, loading, error }
}

// Now use it in any component — one line!
function UsersList() {
  const { data: users, loading, error } = useFetch('https://jsonplaceholder.typicode.com/users')

  if (loading) return <p>Loading...</p>
  if (error) return <p>Error: {error}</p>
  return <ul>{users.map(u => <li key={u.id}>{u.name}</li>)}</ul>
}

function PostsList() {
  const { data: posts, loading, error } = useFetch('https://jsonplaceholder.typicode.com/posts?_limit=5')

  if (loading) return <p>Loading...</p>
  if (error) return <p>Error: {error}</p>
  return <ul>{posts.map(p => <li key={p.id}>{p.title}</li>)}</ul>
}
```

