## useLocalStorage — Persist State Across Refreshes

```jsx
// hooks/useLocalStorage.js
import { useState, useEffect } from 'react'

function useLocalStorage(key, initialValue) {
  // Read from localStorage on first render
  const [value, setValue] = useState(() => {
    try {
      const item = window.localStorage.getItem(key)
      return item ? JSON.parse(item) : initialValue
    } catch {
      return initialValue
    }
  })

  // Write to localStorage whenever value changes
  useEffect(() => {
    try {
      window.localStorage.setItem(key, JSON.stringify(value))
    } catch {
      console.error('Could not save to localStorage')
    }
  }, [key, value])

  return [value, setValue]  // Same API as useState!
}

// Usage — exactly like useState but persisted!
function Settings() {
  const [theme, setTheme] = useLocalStorage('theme', 'light')
  const [fontSize, setFontSize] = useLocalStorage('fontSize', 16)

  return (
    <div>
      <p>Theme: {theme}</p>
      <button onClick={() => setTheme(t => t === 'light' ? 'dark' : 'light')}>
        Toggle Theme
      </button>
      <p>Font Size: {fontSize}px</p>
      <button onClick={() => setFontSize(s => s + 2)}>Increase Font</button>
      <p style={{ fontSize: '12px', color: '#888' }}>
        Refresh the page — your settings are saved!
      </p>
    </div>
  )
}
```

