## Lazy Loading — Split Your Bundle

Instead of loading all your code upfront, lazy load routes and heavy components so they only download when needed.

```jsx
// Without lazy loading — ALL pages load immediately (slow initial load)
import Home from './pages/Home'
import Dashboard from './pages/Dashboard'
import Settings from './pages/Settings'
import Analytics from './pages/Analytics'   // Heavy page loaded even on home
```

```jsx
// With lazy loading — each page loads only when navigated to
import { lazy, Suspense } from 'react'

const Home = lazy(() => import('./pages/Home'))
const Dashboard = lazy(() => import('./pages/Dashboard'))
const Settings = lazy(() => import('./pages/Settings'))
const Analytics = lazy(() => import('./pages/Analytics'))

function App() {
  return (
    <Routes>
      {/* Suspense shows fallback while the lazy component loads */}
      <Suspense fallback={<div>Loading page...</div>}>
        <Route path="/" element={<Home />} />
        <Route path="/dashboard" element={<Dashboard />} />
        <Route path="/settings" element={<Settings />} />
        <Route path="/analytics" element={<Analytics />} />
      </Suspense>
    </Routes>
  )
}
```

