// Render 10,000 items efficiently with react-window
import { FixedSizeList as List } from 'react-window'

const allItems = Array.from({ length: 10000 }, (_, i) => ({ id: i, name: 'Item ' + (i + 1) }))

function Row({ index, style }) {
