## Typing useRef

```tsx
// Specify the DOM element type the ref will point to
import { useRef, useEffect } from "react"

function AutoFocus() {
  // HTMLInputElement tells TypeScript what methods are available on .current
  const inputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    inputRef.current?.focus()   // ?. handles the null case safely
  }, [])

  return <input ref={inputRef} placeholder="Auto-focused!" />
}
