## Common TypeScript + React Patterns

```tsx
// Typing children prop
interface WrapperProps {
  children: React.ReactNode          // Any valid JSX
  className?: string
}

// Typing a component that forwards refs
const Input = React.forwardRef<HTMLInputElement, React.InputHTMLAttributes<HTMLInputElement>>(
  (props, ref) => <input ref={ref} {...props} />
)

// Generic component
function Select<T extends { id: number; label: string }>(props: {
  options: T[]
  onChange: (selected: T) => void
}) {
  return (
    <select onChange={e => {
      const item = props.options.find(o => o.id === Number(e.target.value))
      if (item) props.onChange(item)
    }}>
      {props.options.map(opt => (
        <option key={opt.id} value={opt.id}>{opt.label}</option>
      ))}
    </select>
  )
}
```

