## Creating Your First Store

```js
// store/useCounterStore.js
import { create } from 'zustand'

const useCounterStore = create((set) => ({
  // State
  count: 0,

  // Actions
  increment: () => set(state => ({ count: state.count + 1 })),
  decrement: () => set(state => ({ count: state.count - 1 })),
  reset: () => set({ count: 0 }),
  setCount: (value) => set({ count: value }),
}))

export default useCounterStore
```

```jsx
// Use the store in ANY component — no Provider needed!
import useCounterStore from '../store/useCounterStore'

function Counter() {
  // Subscribe to only what you need — other state changes won't re-render this
  const count = useCounterStore(state => state.count)
  const increment = useCounterStore(state => state.increment)
  const decrement = useCounterStore(state => state.decrement)
  const reset = useCounterStore(state => state.reset)

  return (
    <div>
      <h2>Count: {count}</h2>
      <button onClick={increment}>+</button>
      <button onClick={decrement}>-</button>
      <button onClick={reset}>Reset</button>
    </div>
  )
}

// Same store, totally different component — they share state!
function CounterDisplay() {
  const count = useCounterStore(state => state.count)
  return <p>The current count is: {count}</p>
}
```

