## Step 3: Custom Hook for Note Filtering

```js
// hooks/useFilteredNotes.js
import { useMemo } from 'react'
import useNotesStore from '../store/useNotesStore'

function useFilteredNotes(searchQuery, selectedCategory) {
  const notes = useNotesStore(state => state.notes)

  const filtered = useMemo(() => {
    return notes
      .filter(note => {
        // Filter by category
        if (selectedCategory && note.category !== selectedCategory) return false
        // Filter by search query
        if (searchQuery) {
          const q = searchQuery.toLowerCase()
          return (
            note.title.toLowerCase().includes(q) ||
            note.content.toLowerCase().includes(q)
          )
        }
        return true
      })
      .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
  }, [notes, searchQuery, selectedCategory])

  return filtered
}

export default useFilteredNotes
```

