## Step 4: NoteForm Component

```jsx
// components/NoteForm.jsx
import { useState } from 'react'
import useNotesStore from '../store/useNotesStore'
import { CATEGORIES } from '../types/Note'

const MAX_CONTENT_LENGTH = 500

function NoteForm({ noteToEdit, onDone }) {
  const addNote = useNotesStore(state => state.addNote)
  const updateNote = useNotesStore(state => state.updateNote)

  const [form, setForm] = useState({
    title: noteToEdit?.title || '',
    content: noteToEdit?.content || '',
    category: noteToEdit?.category || 'personal',
  })
  const [errors, setErrors] = useState({})

  function validate() {
    const errs = {}
    if (!form.title.trim()) errs.title = 'Title is required'
    if (!form.content.trim()) errs.content = 'Content is required'
    if (form.content.length > MAX_CONTENT_LENGTH) errs.content = 'Content is too long'
    return errs
  }

  function handleSubmit(e) {
    e.preventDefault()
    const errs = validate()
    if (Object.keys(errs).length > 0) {
      setErrors(errs)
      return
    }

    if (noteToEdit) {
      updateNote(noteToEdit.id, form)
    } else {
      addNote(form)
    }
    onDone()
  }

  function update(field, value) {
    setForm(prev => ({ ...prev, [field]: value }))
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: '' }))
  }

  return (
    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '12px', padding: '16px' }}>
      <h2>{noteToEdit ? 'Edit Note' : 'New Note'}</h2>

      <div>
        <input
          value={form.title}
          onChange={e => update('title', e.target.value)}
          placeholder="Note title..."
          style={{ width: '100%', padding: '10px', borderRadius: '6px', border: errors.title ? '1px solid red' : '1px solid #ddd' }}
        />
        {errors.title && <p style={{ color: 'red', fontSize: '12px' }}>{errors.title}</p>}
      </div>

      <div>
        <textarea
          value={form.content}
          onChange={e => update('content', e.target.value)}
          placeholder="Write your note..."
          rows={6}
          style={{ width: '100%', padding: '10px', borderRadius: '6px', border: errors.content ? '1px solid red' : '1px solid #ddd', resize: 'vertical' }}
        />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '12px', color: form.content.length > MAX_CONTENT_LENGTH ? 'red' : '#888' }}>
          <span>{errors.content}</span>
          <span>{form.content.length} / {MAX_CONTENT_LENGTH}</span>
        </div>
      </div>

      <select
        value={form.category}
        onChange={e => update('category', e.target.value)}
        style={{ padding: '10px', borderRadius: '6px', border: '1px solid #ddd' }}
      >
        {CATEGORIES.map(cat => (
          <option key={cat} value={cat}>{cat.charAt(0).toUpperCase() + cat.slice(1)}</option>
        ))}
      </select>

      <div style={{ display: 'flex', gap: '8px' }}>
        <button type="submit" style={{ flex: 1, padding: '10px', background: '#4f46e5', color: 'white', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>
          {noteToEdit ? 'Save Changes' : 'Add Note'}
        </button>
        <button type="button" onClick={onDone} style={{ flex: 1, padding: '10px', background: '#f1f5f9', border: 'none', borderRadius: '6px', cursor: 'pointer' }}>
          Cancel
        </button>
      </div>
    </form>
  )
}

export default NoteForm
```

