// ─── setImmediate trick to yield to Event Loop ────────────
// Useful when you MUST do sync work but want to stay responsive
function processInChunks(array, chunkSize, processFn) {
  return new Promise((resolve) => {
    let index = 0;
    function processChunk() {
      const end = Math.min(index + chunkSize, array.length);
      for (; index < end; index++) {
        processFn(array[index]);
      }
      if (index < array.length) {
        setImmediate(processChunk); // yield to event loop between chunks
      } else {
        resolve();
      }
    }
    setImmediate(processChunk);
  });
}

