// ─── Extending EventEmitter ───────────────────────────────
class Database extends EventEmitter {
  constructor(url) {
    super();
    this.url = url;
    this.isConnected = false;
    this.queryCount = 0;
  }

  connect() {
    // Simulate async connection
    setTimeout(() => {
      this.isConnected = true;
      this.emit('connect', { url: this.url, timestamp: Date.now() });
    }, 100);
    return this;
  }

  async query(sql, params = []) {
    if (!this.isConnected) {
      this.emit('error', new Error('Not connected to database'));
      return null;
    }

    this.emit('query:start', { sql, params });

    try {
      // Simulate DB query
      await new Promise(r => setTimeout(r, 50));
      const result = { rows: [], rowCount: 0 };
      this.queryCount++;
      this.emit('query:end', { sql, result, queryCount: this.queryCount });
      return result;
    } catch (err) {
      this.emit('query:error', { sql, err });
      throw err;
    }
  }

  disconnect() {
    this.isConnected = false;
    this.emit('disconnect');
    this.removeAllListeners();
  }
}

