// Random int in range (cryptographically secure)
function secureRandomInt(min, max) {
  const range = max - min;
  const bytesNeeded = Math.ceil(Math.log2(range) / 8);
  const maxValid = Math.floor(256 ** bytesNeeded / range) * range;
  let rand;
  do {
    rand = crypto.randomBytes(bytesNeeded).readUIntBE(0, bytesNeeded);
  } while (rand >= maxValid); // rejection sampling for uniform distribution
  return min + (rand % range);
}

// ─── HMAC — Verify Request Signatures ────────────────────
// Used for webhook verification (Stripe, GitHub, etc.)
const SECRET = process.env.WEBHOOK_SECRET || 'my-secret-key';

function createSignature(payload) {
  return crypto
    .createHmac('sha256', SECRET)
    .update(typeof payload === 'string' ? payload : JSON.stringify(payload))
    .digest('hex');
}

function verifySignature(payload, receivedSignature) {
  const expectedSignature = createSignature(payload);
  const expected = Buffer.from(expectedSignature);
  const received = Buffer.from(receivedSignature);

  // Use timingSafeEqual to prevent timing attacks!
  if (expected.length !== received.length) return false;
  return crypto.timingSafeEqual(expected, received);
}

