// ─── Reading a large file line-by-line with streams ───────
const readline = require('readline');

async function processLargeFile(filePath) {
  const fileStream = fs.createReadStream(filePath, {
    encoding: 'utf8',
    highWaterMark: 64 * 1024, // 64KB chunks (default)
  });

  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity // handle Windows line endings
  });

  let lineCount = 0;
  let errorCount = 0;

  for await (const line of rl) {
    lineCount++;
    if (line.includes('ERROR')) errorCount++;
    // Process each line without loading the whole file!
  }

  console.log(`Processed ${lineCount} lines, found ${errorCount} errors`);
}

// ─── Compress a file using streams + pipeline ─────────────
async function compressFile(input, output) {
  await pipeline(
    fs.createReadStream(input),
    zlib.createGzip(),          // Transform: compress with gzip
    fs.createWriteStream(output)
  );

  const inputStat = await fs.promises.stat(input);
  const outputStat = await fs.promises.stat(output);
  const ratio = ((1 - outputStat.size / inputStat.size) * 100).toFixed(1);
  console.log(`Compressed: ${inputStat.size} → ${outputStat.size} bytes (${ratio}% smaller)`);
}

// ─── Writing data to a stream ─────────────────────────────
async function writeCSV(data, outputPath) {
  const writeStream = fs.createWriteStream(outputPath, { encoding: 'utf8' });

  // Write header
  writeStream.write('id,name,email,createdAt
');

  for (const row of data) {
    const line = `${row.id},"${row.name}",${row.email},${row.createdAt}
`;

    // write() returns false if buffer is full (backpressure!)
    const canContinue = writeStream.write(line);
    if (!canContinue) {
      // Wait for drain event before writing more
      await new Promise(resolve => writeStream.once('drain', resolve));
    }
  }

  // Close the stream
  await new Promise((resolve, reject) => {
    writeStream.end(resolve);
    writeStream.once('error', reject);
  });

  console.log(`CSV written to ${outputPath}`);
}

const { Transform } = require('stream');
const fs = require('fs');
const { pipeline } = require('stream').promises;

// ─── Custom Transform Stream ──────────────────────────────
class CSVParser extends Transform {
  constructor(options = {}) {
    super({ ...options, objectMode: true }); // output JS objects
    this._header = null;
    this._remainder = '';
    this._lineCount = 0;
  }

  _transform(chunk, encoding, callback) {
    // chunk is a Buffer, convert to string
    const data = this._remainder + chunk.toString('utf8');
    const lines = data.split('
');

    // Save potentially incomplete last line for next chunk
    this._remainder = lines.pop();

    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed) continue;

      const values = trimmed.split(',').map(v => v.replace(/^"|"$/g, ''));

      if (!this._header) {
        this._header = values; // first line is header
        continue;
      }

      // Create object from header and values
      const row = {};
      this._header.forEach((key, i) => {
        row[key] = values[i] ?? null;
      });

      this._lineCount++;
      this.push(row); // push object downstream
    }

    callback(); // signal we're done processing this chunk
  }

  _flush(callback) {
    // Process remaining data when stream ends
    if (this._remainder.trim() && this._header) {
      const values = this._remainder.trim().split(',');
      const row = {};
      this._header.forEach((key, i) => {
        row[key] = values[i] ?? null;
      });
      this.push(row);
    }
    console.log(`Parsed ${this._lineCount} rows`);
    callback();
  }
}

// ─── Usage: Stream a 1GB CSV file without loading it all ──
async function processCSV(csvPath) {
  const results = [];

  await pipeline(
    fs.createReadStream(csvPath),
    new CSVParser(),
    new Transform({
      objectMode: true,
      transform(row, enc, cb) {
        // Filter and transform each row
        if (Number(row.age) >= 18) {
          results.push(row);
        }
        cb();
      }
    })
  );

  console.log(`Found ${results.length} adult users`);
  return results;
}

