const express = require('express');
const cors = require('cors');
const helmet = require('helmet');
const morgan = require('morgan');
const compression = require('compression');
const rateLimit = require('express-rate-limit');
const cookieParser = require('cookie-parser');

const app = express();

// ─── 1. Security Headers (helmet) ────────────────────────
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https://cdn.example.com'],
      scriptSrc: ["'self'", "'unsafe-inline'"], // adjust for your needs
    }
  },
  crossOriginEmbedderPolicy: false // may break some browsers
}));

// ─── 2. CORS ──────────────────────────────────────────────
const allowedOrigins = [
  'http://localhost:3000',
  'https://myapp.com',
  process.env.FRONTEND_URL
].filter(Boolean);

app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (Postman, curl, mobile apps)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error(`CORS blocked: ${origin}`));
    }
  },
  credentials: true,  // allow cookies and auth headers
  methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-API-Key'],
  maxAge: 86400 // cache preflight for 24 hours
}));

// ─── 3. Request Logging ───────────────────────────────────
if (process.env.NODE_ENV === 'development') {
  app.use(morgan('dev')); // colorful dev output
} else {
  app.use(morgan('combined')); // Apache-style for production logs
}

// ─── 4. Compression ───────────────────────────────────────
app.use(compression({
  level: 6, // compression level (1=fastest, 9=smallest)
  threshold: 1024, // only compress responses > 1KB
  filter: (req, res) => {
    if (req.headers['x-no-compression']) return false;
    return compression.filter(req, res); // default filter
  }
}));

// ─── 5. Body Parsers ──────────────────────────────────────
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true, limit: '10mb' }));
app.use(cookieParser(process.env.COOKIE_SECRET));

// ─── 6. Global Rate Limiting ──────────────────────────────
