const jwt = require('jsonwebtoken');

// ─── Request ID Middleware ────────────────────────────────
// Adds a unique ID to every request for log correlation
const crypto = require('crypto');
const requestId = (req, res, next) => {
  req.id = req.headers['x-request-id'] || crypto.randomUUID();
  res.setHeader('X-Request-ID', req.id);
  next();
};

// ─── Response Time Middleware ─────────────────────────────
const responseTime = (req, res, next) => {
  const startTime = process.hrtime.bigint();

  res.on('finish', () => {
    const duration = Number(process.hrtime.bigint() - startTime) / 1e6; // ms
    res.setHeader('X-Response-Time', `${duration.toFixed(2)}ms`);

    if (duration > 1000) { // slow request warning
      console.warn(`⚠️  Slow request: ${req.method} ${req.path} took ${duration.toFixed(0)}ms`);
    }
  });
  next();
};

// ─── JWT Authentication Middleware ───────────────────────
const protect = async (req, res, next) => {
  try {
    let token;

    // Check Authorization header: "Bearer <token>"
    if (req.headers.authorization?.startsWith('Bearer ')) {
      token = req.headers.authorization.split(' ')[1];
    }
    // Or check httpOnly cookie (more secure)
    else if (req.cookies?.accessToken) {
      token = req.cookies.accessToken;
    }

    if (!token) {
      return res.status(401).json({
        success: false,
        error: 'Access denied: No authentication token provided'
      });
    }

    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    // Optionally fetch fresh user from DB to check if still active
    // const user = await User.findById(decoded.id);
    // if (!user || !user.isActive) throw new Error('User deactivated');

    req.user = decoded; // attach user info for subsequent middleware
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ success: false, error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ success: false, error: 'Invalid token' });
    }
    next(err);
  }
};

// ─── Role Authorization Middleware ───────────────────────
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ success: false, error: 'Not authenticated' });
    }
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        success: false,
        error: `Access denied: requires role ${roles.join(' or ')}, you have ${req.user.role}`
      });
    }
    next();
  };
};

// Usage in routes:
// router.get('/admin/users', protect, authorize('admin', 'superadmin'), getUsers);
// router.patch('/posts/:id', protect, authorize('editor', 'admin'), updatePost);

// ─── Request Validation Middleware (with Zod or Joi) ─────
const validateBody = (schema) => {
  return (req, res, next) => {
    const { error, value } = schema.validate(req.body, { abortEarly: false });
    if (error) {
      const details = error.details.map(d => ({
        field: d.path.join('.'),
        message: d.message.replace(/['"]/g, '')
      }));
      return res.status(422).json({
        success: false,
        error: 'Validation failed',
        details
      });
    }
    req.body = value; // replace with sanitized/coerced value
    next();
  };
};

module.exports = { requestId, responseTime, protect, authorize, validateBody };

// middlewares/error.middleware.js

// ─── Custom Error Classes ─────────────────────────────────
class AppError extends Error {
  constructor(message, statusCode, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.status = statusCode >= 400 && statusCode < 500 ? 'fail' : 'error';
    this.isOperational = isOperational; // known/expected errors
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(errors) {
    super('Validation failed', 422);
    this.errors = errors;
  }
}

class NotFoundError extends AppError {
  constructor(resource = 'Resource') {
    super(`${resource} not found`, 404);
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Authentication required') {
    super(message, 401);
  }
}

// ─── Handle specific Mongoose/MongoDB errors ──────────────
function handleMongoErrors(err) {
  if (err.name === 'CastError') {
    return new AppError(`Invalid ${err.path}: ${err.value}`, 400);
  }
  if (err.code === 11000) {
    const field = Object.keys(err.keyValue)[0];
    return new AppError(`${field} '${err.keyValue[field]}' already exists`, 409);
  }
  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors).map(e => ({
      field: e.path, message: e.message
    }));
    return new ValidationError(errors);
  }
  return err;
}

// ─── Global Error Handler ─────────────────────────────────
const globalErrorHandler = (err, req, res, next) => {
  let error = handleMongoErrors(err);

  // Log error (use a proper logger in production)
  if (process.env.NODE_ENV === 'development') {
    console.error('💥 ERROR:', {
      message: error.message,
      stack: error.stack,
      requestId: req.id
    });
  } else if (!error.isOperational) {
    // Only log unexpected errors in production
    console.error('💥 UNHANDLED ERROR:', error);
  }

  const statusCode = error.statusCode || 500;
  const response = {
    success: false,
    status: error.status || 'error',
    error: error.message || 'Something went wrong',
    requestId: req.id
  };

  if (process.env.NODE_ENV === 'development') {
    response.stack = error.stack;
  }
  if (error.errors) {
    response.details = error.errors;
  }

  res.status(statusCode).json(response);
};

// Handle unhandled promise rejections and uncaught exceptions
process.on('unhandledRejection', (err) => {
  console.error('Unhandled Promise Rejection:', err);
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

module.exports = { AppError, NotFoundError, UnauthorizedError, globalErrorHandler };

