// services/user.service.js — All business logic lives here
const User = require('../models/User');
const bcrypt = require('bcryptjs');
const { AppError } = require('../middlewares/error.middleware');

exports.getUsers = async ({ page, limit, search, sort = 'createdAt', order = 'desc' }) => {
  const skip = (page - 1) * limit;

  // Build dynamic query
  const query = {};
  if (search) {
    query.$or = [
      { name: { $regex: search, $options: 'i' } },
      { email: { $regex: search, $options: 'i' } }
    ];
  }

  // Execute query and count in parallel
  const [data, total] = await Promise.all([
    User.find(query)
      .select('-password -__v') // exclude sensitive fields
      .sort({ [sort]: order === 'asc' ? 1 : -1 })
      .skip(skip)
      .limit(limit)
      .lean(), // returns plain JS objects instead of Mongoose Documents (faster)
    User.countDocuments(query)
  ]);

  return {
    data,
    pagination: {
      total,
      page,
      limit,
      pages: Math.ceil(total / limit),
      hasNext: page * limit < total,
      hasPrev: page > 1
    }
  };
};

exports.getUserById = async (id) => {
  return User.findById(id).select('-password').lean();
};

exports.createUser = async ({ name, email, password, role }) => {
  // Check uniqueness
  const exists = await User.findOne({ email: email.toLowerCase() });
  if (exists) throw new AppError('Email already registered', 409);

  // Hash password (NEVER store plain text!)
  const hashedPassword = await bcrypt.hash(password, 12);

  const user = await User.create({
    name,
    email: email.toLowerCase(),
    password: hashedPassword,
    role: role || 'user'
  });

  const { password: _, ...userWithoutPassword } = user.toObject();
  return userWithoutPassword;
};

exports.updateUser = async (id, updates) => {
  // Never allow updating password or role this way — separate endpoints
  const { password, role, ...safeUpdates } = updates;

  return User.findByIdAndUpdate(
    id,
    { $set: safeUpdates },
