// utils/apiFeatures.js — Reusable query builder
class APIFeatures {
  constructor(query, queryString) {
    this.query = query;          // Mongoose query
    this.queryString = queryString; // req.query
  }

  filter() {
    // Clone query params and remove special fields
    const queryObj = { ...this.queryString };
    const excluded = ['page', 'sort', 'limit', 'fields', 'search'];
    excluded.forEach(field => delete queryObj[field]);

    // Support MongoDB operators: price[gte]=100 → { price: { $gte: 100 } }
    let queryStr = JSON.stringify(queryObj);
    queryStr = queryStr.replace(/ (gte|gt|lte|lt|in|ne) /g, match => `$${match}`);

    this.query = this.query.find(JSON.parse(queryStr));
    return this;
  }

  search(fields) {
    if (this.queryString.search) {
      const regex = new RegExp(this.queryString.search, 'i');
      this.query = this.query.find({
        $or: fields.map(field => ({ [field]: regex }))
      });
    }
    return this;
  }

  sort() {
    if (this.queryString.sort) {
      // Allow: ?sort=price,-name (price asc, name desc)
      const sortBy = this.queryString.sort.split(',').join(' ');
      this.query = this.query.sort(sortBy);
    } else {
      this.query = this.query.sort('-createdAt'); // default
    }
    return this;
  }

  selectFields() {
    if (this.queryString.fields) {
      // Allow: ?fields=name,email,price (select only these)
      const fields = this.queryString.fields.split(',').join(' ');
      this.query = this.query.select(fields);
    } else {
      this.query = this.query.select('-__v');
    }
    return this;
  }

  paginate() {
    const page = parseInt(this.queryString.page) || 1;
    const limit = Math.min(parseInt(this.queryString.limit) || 20, 100);
    const skip = (page - 1) * limit;
    this.query = this.query.skip(skip).limit(limit);
    this._pagination = { page, limit };
    return this;
  }
}

// Usage in controller:
// GET /products?price[gte]=100&price[lte]=500&sort=price&fields=name,price&page=2&limit=10&search=laptop
exports.getProducts = async (req, res, next) => {
  try {
    const features = new APIFeatures(Product.find(), req.query)
      .filter()
      .search(['name', 'description', 'brand'])
      .sort()
      .selectFields()
      .paginate();

    const [data, total] = await Promise.all([
      features.query.lean(),
      Product.countDocuments()
    ]);

    res.json({
      success: true,
      data,
      results: data.length,
      total
    });
  } catch (err) { next(err); }
};

