const JWT_ACCESS_SECRET = process.env.JWT_ACCESS_SECRET;
const JWT_REFRESH_SECRET = process.env.JWT_REFRESH_SECRET;
const ACCESS_TOKEN_EXPIRES = '15m';
const REFRESH_TOKEN_EXPIRES = '7d';

// ─── Token Generation ─────────────────────────────────────
function generateAccessToken(userId, role) {
  return jwt.sign(
    { id: userId, role, type: 'access' },
    JWT_ACCESS_SECRET,
    { expiresIn: ACCESS_TOKEN_EXPIRES, issuer: 'myapp.com' }
  );
}

function generateRefreshToken(userId) {
  return jwt.sign(
    { id: userId, type: 'refresh' },
    JWT_REFRESH_SECRET,
    { expiresIn: REFRESH_TOKEN_EXPIRES }
  );
}

function setRefreshTokenCookie(res, token) {
  res.cookie('refreshToken', token, {
    httpOnly: true,   // JS cannot read this cookie
    secure: process.env.NODE_ENV === 'production', // HTTPS only in prod
    sameSite: 'strict', // CSRF protection
    maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days in ms
  });
}

// ─── Register ─────────────────────────────────────────────
exports.register = async ({ name, email, password }) => {
  const existingUser = await User.findOne({ email: email.toLowerCase() });
  if (existingUser) throw new AppError('Email already in use', 409);

  const user = await User.create({ name, email, password }); // hash done in pre-save hook

  const accessToken = generateAccessToken(user._id, user.role);
  const refreshToken = generateRefreshToken(user._id);

  return { user: { id: user._id, name: user.name, email: user.email, role: user.role }, accessToken, refreshToken };
};

// ─── Login ────────────────────────────────────────────────
exports.login = async ({ email, password }) => {
  // 1. Find user (include password which is excluded by default)
  const user = await User.findOne({ email: email.toLowerCase() }).select('+password +isActive');

  // 2. Check user exists AND password is correct
  // IMPORTANT: check both in one step to prevent username enumeration timing attacks
  if (!user || !(await bcrypt.compare(password, user.password))) {
    throw new AppError('Invalid email or password', 401);
  }

  if (!user.isActive) throw new AppError('Account deactivated. Contact support.', 403);

  const accessToken = generateAccessToken(user._id, user.role);
  const refreshToken = generateRefreshToken(user._id);

  return {
    user: { id: user._id, name: user.name, email: user.email, role: user.role },
    accessToken,
    refreshToken
  };
};

// ─── Refresh Token ────────────────────────────────────────
exports.refreshAccessToken = async (refreshToken) => {
  if (!refreshToken) throw new AppError('Refresh token required', 401);

  try {
    const decoded = jwt.verify(refreshToken, JWT_REFRESH_SECRET);
    if (decoded.type !== 'refresh') throw new Error('Invalid token type');

    const user = await User.findById(decoded.id).select('role isActive');
    if (!user || !user.isActive) throw new AppError('User not found', 401);

    return generateAccessToken(user._id, user.role);
  } catch (err) {
    if (err instanceof AppError) throw err;
    throw new AppError('Invalid or expired refresh token', 401);
  }
};

// ─── Forgot Password ──────────────────────────────────────
exports.forgotPassword = async (email) => {
  const user = await User.findOne({ email: email.toLowerCase() });
  // Don't reveal if email exists or not!
  if (!user) return; // silently do nothing

  const resetToken = user.createPasswordResetToken(); // generates & stores hashed version
  await user.save({ validateBeforeSave: false });

  return resetToken; // send this via email
};

exports.resetPassword = async (token, newPassword) => {
  const hashedToken = crypto.createHash('sha256').update(token).digest('hex');

  const user = await User.findOne({
    passwordResetToken: hashedToken,
    passwordResetExpires: { $gt: Date.now() } // not expired
  });

  if (!user) throw new AppError('Invalid or expired reset token', 400);

  user.password = newPassword; // pre-save hook will hash it
  user.passwordResetToken = undefined;
  user.passwordResetExpires = undefined;
  await user.save();
};

