Every async Express handler needs try/catch. This gets repetitive:
```js
router.get('/', async (req, res, next) => {
  try { /* ... */ } catch(err) { next(err); }
});
```

The solution: an `asyncHandler` (or `catchAsync`) higher-order function that wraps async handlers and automatically catches errors, passing them to `next()`.

codeSnippets.code:
// utils/asyncHandler.js
// Wraps async route handlers — no more try/catch boilerplate!
const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

// Arrow function version (more concise)
const catchAsync = fn => (req, res, next) =>
  fn(req, res, next).catch(next);

module.exports = { asyncHandler, catchAsync };

// Usage — before vs after
// ─── BEFORE (tedious) ────────────────────────────────────
router.get('/users', async (req, res, next) => {
  try {
    const users = await User.find();
    res.json({ success: true, data: users });
  } catch (err) { next(err); }
});

// ─── AFTER (clean) ───────────────────────────────────────
router.get('/users', catchAsync(async (req, res) => {
  const users = await User.find();
  res.json({ success: true, data: users });
}));

// ─── Custom Error Classes ─────────────────────────────────
// middlewares/errors.js
class AppError extends Error {
  constructor(message, statusCode, errors = null) {
    super(message);
    this.statusCode = statusCode;
    this.status = String(statusCode).startsWith('4') ? 'fail' : 'error';
    this.isOperational = true;
    this.errors = errors; // validation details
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(errors) {
    super('Validation failed', 422, errors);
  }
}

class NotFoundError extends AppError {
  constructor(resource = 'Resource') {
    super(`${resource} not found`, 404);
  }
}

class DuplicateError extends AppError {
  constructor(field) {
    super(`${field} already exists`, 409);
    this.field = field;
  }
}

class UnauthorizedError extends AppError {
  constructor(message = 'Not authenticated') {
    super(message, 401);
  }
}

class ForbiddenError extends AppError {
  constructor(message = 'Not authorized') {
    super(message, 403);
  }
}

module.exports = { AppError, ValidationError, NotFoundError, DuplicateError, UnauthorizedError, ForbiddenError };

