      }),
    confirmPassword: Joi.valid(Joi.ref('password')).required()
      .messages({ 'any.only': 'Passwords must match' }),
    role: Joi.string().valid('user', 'editor').default('user')
  }),

  createPost: Joi.object({
    title: Joi.string().trim().min(3).max(100).required(),
    content: Joi.string().min(10).max(10000).required(),
    tags: Joi.array().items(Joi.string().trim().lowercase()).max(5).default([]),
    status: Joi.string().valid('draft', 'published').default('draft'),
    publishAt: Joi.date().iso().min('now').optional()
  }),

  updateUser: Joi.object({
    name: Joi.string().trim().min(2).max(50),
    bio: Joi.string().max(500).allow('').optional(),
    preferences: Joi.object({
      theme: Joi.string().valid('light', 'dark', 'system'),
      notifications: Joi.boolean(),
      language: Joi.string().valid('en', 'es', 'fr', 'de')
    }).optional()
  }).min(1) // at least one field required
};

// Validation middleware factory
const validate = (schemaName, property = 'body') => {
  return (req, res, next) => {
    const schema = schemas[schemaName];
    const { error, value } = schema.validate(req[property], {
      abortEarly: false,  // collect ALL errors, not just first
      stripUnknown: true, // remove fields not in schema
      convert: true       // coerce types (string to number, etc.)
    });

    if (error) {
      const errors = error.details.map(d => ({
        field: d.path.join('.'),
        message: d.message.replace(/['"]/g, '')
      }));
      return next(new ValidationError(errors));
    }

    req[property] = value; // use sanitized/coerced value
    next();
  };
};

