      connectSrc: ["'self'", 'https://api.example.com'],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: []
    }
  },
  hsts: {
    maxAge: 31536000,        // 1 year in seconds
    includeSubDomains: true,
    preload: true
  }
}));

// ─── 2. CORS with Whitelist ───────────────────────────────
const ALLOWED_ORIGINS = ['https://myapp.com', 'https://admin.myapp.com'];
app.use(cors({
  origin: (origin, cb) => {
    if (!origin || ALLOWED_ORIGINS.includes(origin)) return cb(null, true);
    cb(new Error('Not allowed by CORS'));
  },
  credentials: true,
  methods: ['GET', 'POST', 'PATCH', 'DELETE'],
}));

// ─── 3. Rate Limiting ─────────────────────────────────────
// Global limit
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 500,
  message: { success: false, error: 'Too many requests, slow down!' },
  standardHeaders: true,
  legacyHeaders: false
}));

// Strict limit for auth endpoints
app.use('/api/v1/auth/login', rateLimit({ windowMs: 15 * 60 * 1000, max: 10 }));
app.use('/api/v1/auth/register', rateLimit({ windowMs: 60 * 60 * 1000, max: 5 }));
app.use('/api/v1/auth/forgot-password', rateLimit({ windowMs: 60 * 60 * 1000, max: 3 }));

// Progressive slow-down (alternative to hard blocking)
app.use('/api/v1/auth/login', slowDown({
  windowMs: 15 * 60 * 1000,
  delayAfter: 3, // allow 3 fast, then start slowing
  delayMs: (hits) => hits * 500, // add 500ms per excess request
}));

// ─── 4. Body Parsing Limits ───────────────────────────────
app.use(express.json({ limit: '10kb' })); // Prevent large payload attacks
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ─── 5. NoSQL Injection Prevention ───────────────────────
app.use(mongoSanitize({
  replaceWith: '_',  // replace $ and . with _
  onSanitize: ({ key }) => {
    console.warn(`⚠️  NoSQL injection attempt detected in key: ${key}`);
  }
}));

// ─── 6. XSS Prevention ───────────────────────────────────
app.use(xss()); // strips HTML tags from req.body, req.query, req.params

// ─── 7. HTTP Parameter Pollution Prevention ───────────────
// Prevents: GET /api?sort=name&sort=email (array injection)
app.use(hpp({
  whitelist: ['tags', 'category'] // allow arrays for these params only
}));

const { execFile } = require('child_process'); // NOT exec!
const validator = require('validator');

// ─── Safe Command Execution ───────────────────────────────
// NEVER: exec(`convert ${userInput} output.jpg`) — shell injection!
function convertImage(inputPath, outputPath) {
  return new Promise((resolve, reject) => {
    // execFile uses argument array — no shell, no injection!
    execFile('convert', [inputPath, '-resize', '800x600', outputPath], (err, stdout, stderr) => {
      if (err) reject(new Error('Image conversion failed'));
      else resolve(outputPath);
    });
  });
}

// ─── Input Sanitization Utilities ────────────────────────
const sanitizeInput = {
  // Remove HTML tags for plain text fields
  text: (str) => str ? str.replace(/<[^>]*>/g, '').trim() : str,

  // Escape HTML for display in templates
  html: (str) => validator.escape(str || ''),

  // Normalize email
  email: (str) => validator.normalizeEmail(str || '') || str,

  // Validate and parse ObjectId
  objectId: (id) => {
    if (!validator.isMongoId(id)) throw new Error('Invalid ID format');
    return id;
  },

  // Sanitize for safe inclusion in regex
  regexSafe: (str) => str.replace(/[.*+?^$)(}{|[\]\\]/g, '\\$&')
};

// ─── Security Audit Logger ────────────────────────────────
const securityLog = {
  failedLogin: (email, ip) => {
    console.warn(`[SECURITY] Failed login: ${email} from ${ip} at ${new Date().toISOString()}`);
  },
  suspiciousActivity: (action, userId, ip) => {
    console.warn(`[SECURITY] Suspicious: ${action} by user ${userId} from ${ip}`);
  },
  privilegeEscalation: (userId, attemptedRole, actualRole) => {
    console.error(`[SECURITY] Privilege escalation attempt: user ${userId} has ${actualRole}, tried ${attemptedRole}`);
  }
};

// ─── Password Complexity Validator ───────────────────────
function validatePasswordStrength(password) {
  const issues = [];
  if (password.length < 8)          issues.push('At least 8 characters');
  if (!/[a-z]/.test(password))      issues.push('At least one lowercase letter');
  if (!/[A-Z]/.test(password))      issues.push('At least one uppercase letter');
  if (!/d/.test(password))         issues.push('At least one number');
  if (!/[@$!%*?&]/.test(password)) issues.push('At least one special character (@$!%*?&)');

  // Check against common passwords
  const commonPasswords = ['password', '123456', 'password123', 'qwerty'];
  if (commonPasswords.includes(password.toLowerCase())) {
    issues.push('Password is too common');
  }

  return { isValid: issues.length === 0, issues };
}

