// ─── Process image and upload to Cloudinary ───────────────
async function processAndUploadImage(file, options = {}) {
  const {
    width = 800,
    height = 800,
    quality = 80,
    folder = 'uploads',
    format = 'webp',
    fit = 'inside'
  } = options;

  // Process image with Sharp
  const processedBuffer = await sharp(file.buffer)
    .resize(width, height, {
      fit,           // 'inside', 'cover', 'contain', 'fill'
      withoutEnlargement: true // don't upscale small images
    })
    .toFormat(format, { quality })
    .toBuffer();

  // Get image metadata
  const metadata = await sharp(file.buffer).metadata();
  console.log(`Original: ${metadata.width}x${metadata.height}, ${file.size} bytes`);
  console.log(`Processed: ${processedBuffer.length} bytes (format: ${format})`);

  // Upload to Cloudinary via stream
  const result = await new Promise((resolve, reject) => {
    const uploadStream = cloudinary.uploader.upload_stream(
      {
        folder,
        resource_type: 'image',
        format,
        transformation: [{ quality: 'auto', fetch_format: 'auto' }]
      },
      (err, result) => err ? reject(err) : resolve(result)
    );

    // Convert Buffer to Readable stream and pipe to Cloudinary
    Readable.from(processedBuffer).pipe(uploadStream);
  });

  return {
    url: result.secure_url,
    publicId: result.public_id,
    width: result.width,
    height: result.height,
    format: result.format,
    bytes: result.bytes
  };
}

// ─── Generate Multiple Sizes ──────────────────────────────
async function generateResponsiveImages(buffer, folder) {
  const sizes = [
    { name: 'thumbnail', width: 150, height: 150, fit: 'cover' },
    { name: 'medium', width: 600, height: 600, fit: 'inside' },
    { name: 'large', width: 1200, height: 1200, fit: 'inside' }
  ];

  const uploads = await Promise.all(sizes.map(size =>
    processAndUploadImage({ buffer }, { ...size, folder })
      .then(result => ({ [size.name]: result.url }))
  ));

  return Object.assign({}, ...uploads);
}

