const http = require('http');
const WebSocket = require('ws');

// 1. Create a standard HTTP server
const server = http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/plain' });
  res.end('WebSocket server running');
});

// 2. Create WebSocket server attached to the HTTP server
// This allows both HTTP and WS to share the same port (e.g., 8080)
const wss = new WebSocket.Server({ server });

// Keep track of connected clients
const clients = new Set();

// 3. Listen for connections
wss.on('connection', (ws, req) => {
  const ip = req.socket.remoteAddress;
  console.log(`[+] New connection from ${ip}. Total clients: ${wss.clients.size}`);

  clients.add(ws);

  // Send welcome message to the new client
  ws.send(JSON.stringify({ 
    type: 'system', 
    message: 'Welcome to the raw WebSocket server!' 
  }));

  // Listen for messages from this client
  ws.on('message', (messageAsString) => {
    // ws package returns Buffers by default, must convert to string
    console.log(`Received: ${messageAsString}`);

    // Custom broadcasting implementation
    // (ws doesn't have a built-in broadcast method)
    for (const client of clients) {
      if (client !== ws && client.readyState === WebSocket.OPEN) {
        client.send(messageAsString); // Send Buffer directly or convert to string
      }
    }
  });

  // Handle client disconnect
  ws.on('close', () => {
    clients.delete(ws);
    console.log(`[-] Client disconnected. Total clients: ${clients.size}`);
  });

  // Handle connection errors
  ws.on('error', (err) => {
    console.error('WebSocket Error:', err.message);
  });
});

