// 3. Listen for connections
io.on('connection', (socket) => {
  console.log(`✅ User connected: ${socket.id}`);

  // ─── Event Listeners ────────────────────────────────────

  // Custom event listener (not just 'message')
  socket.on('chat:message', (data) => {
    console.log('Received:', data);

    // io.emit = sends to EVERYONE, including the sender
    // io.emit('chat:broadcast', data);

    // socket.broadcast.emit = sends to EVERYONE EXCEPT sender
    socket.broadcast.emit('chat:broadcast', {
      senderId: socket.id,
      text: data.text,
      time: new Date()
    });
  });

  // ─── Rooms ──────────────────────────────────────────────

  socket.on('room:join', (roomName) => {
    socket.join(roomName);
    console.log(`${socket.id} joined room: ${roomName}`);

    // Notify others in the room
    socket.to(roomName).emit('room:notification', `A new user joined ${roomName}`);
  });

  socket.on('room:leave', (roomName) => {
    socket.leave(roomName);
    socket.to(roomName).emit('room:notification', `A user left ${roomName}`);
  });

  // Send message to specific room
  socket.on('room:message', ({ roomName, text }) => {
    // io.to() sends to everyone in the room
    io.to(roomName).emit('room:message:received', { senderId: socket.id, text });
  });

  // ─── Disconnection ──────────────────────────────────────
  socket.on('disconnect', (reason) => {
    console.log(`❌ User disconnected: ${socket.id} (Reason: ${reason})`);
    // Note: Socket automatically leaves all rooms upon disconnect!
  });
});

