const { Server } = require('socket.io');
const { createClient } = require('redis');
const { createAdapter } = require('@socket.io/redis-adapter');

const io = new Server(3000);

// Create two Redis clients: one for publishing, one for subscribing
const pubClient = createClient({ url: 'redis://localhost:6379' });
const subClient = pubClient.duplicate();

async function setupRedisAdapter() {
  // Connect both clients to Redis
  await Promise.all([
    pubClient.connect(),
    subClient.connect()
  ]);

  // Attach the adapter to Socket.io
  io.adapter(createAdapter(pubClient, subClient));

  console.log('✅ Socket.io Redis Adapter attached. App is ready to scale!');
}

setupRedisAdapter();

io.on('connection', (socket) => {
  // This broadcast will now magically reach clients connected to OTHER Node.js instances!
  socket.on('message', (msg) => {
    socket.broadcast.emit('message', msg);
  });
});

// Socket.io Middleware for Authentication
const jwt = require('jsonwebtoken');

// io.use() runs during the initial handshake
io.use((socket, next) => {
  // 1. Extract token. Clients can pass it in 'auth' payload
  // e.g., const socket = io({ auth: { token: 'jwt-here' } })
  const token = socket.handshake.auth.token;

  if (!token) {
    // Calling next with an Error rejects the connection
    return next(new Error('Authentication error: No token provided'));
  }

  // 2. Verify the JWT
  jwt.verify(token, process.env.JWT_SECRET, (err, decoded) => {
    if (err) {
      return next(new Error('Authentication error: Invalid token'));
    }

    // 3. Attach user info to the socket object!
    // Now EVERY event listener has access to the user's ID
    socket.user = decoded; 

    next(); // Accept the connection
  });
});

io.on('connection', (socket) => {
  console.log(`✅ Authenticated user connected: ${socket.user.id}`);

  // Common pattern: Auto-join a room specific to this user's ID.
  // This makes it easy to send notifications to a specific user,
  // even if they are logged in on multiple tabs/devices!
  socket.join(socket.user.id);

  socket.on('send_notification', (data) => {
    // Send to a specific user by their ID
    io.to(data.targetUserId).emit('notification', {
      from: socket.user.id,
      message: data.message
    });
  });
});

