      log_date_format: "YYYY-MM-DD HH:mm Z",

      // Environment specific variables
      env: {
        NODE_ENV: "development",
      },
      env_production: {
        NODE_ENV: "production",
        PORT: 5000,
        // DON'T put hardcoded passwords here if committing to Git!
        // Inject them via CI/CD or server environment
      }
    }
  ]
};

// ─── Graceful Startup in src/index.js ────────────────────
/*
const server = app.listen(PORT, async () => {
  console.log('Server started');

  // Wait for DB to connect before telling PM2 we are ready
  await connectDB();

  // Tell PM2 the app is ready to receive traffic (used with wait_ready: true)
  if (process.send) {
    process.send('ready');
  }
});
*/

// ─── Useful PM2 Commands ─────────────────────────────────
/*
pm2 start ecosystem.config.js --env production  # Start app
pm2 list                                        # View status of all apps
pm2 logs                                        # Stream logs
pm2 monit                                       # Terminal dashboard (CPU/RAM)
pm2 reload my-node-api                          # Zero-downtime restart (loads new code)
pm2 restart my-node-api                         # Hard restart (drops connections)
pm2 stop my-node-api                            # Stop app
pm2 delete my-node-api                          # Remove from PM2
pm2 startup                                     # Generate OS startup script
pm2 save                                        # Save current list to restart on boot
*/

# /etc/nginx/sites-available/myapp

# Redirect HTTP to HTTPS
server {
    listen 80;
    listen [::]:80;
    server_name api.myapp.com;
    return 301 https://$host$request_uri;
}

# Main HTTPS Server
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name api.myapp.com;

    # SSL Certificates (Managed by Let's Encrypt / Certbot)
    ssl_certificate /etc/letsencrypt/live/api.myapp.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/api.myapp.com/privkey.pem;

    # Security Headers
    add_header X-Frame-Options "SAMEORIGIN";
    add_header X-XSS-Protection "1; mode=block";
    add_header X-Content-Type-Options "nosniff";

    # Serve static frontend files (if serving SPA from same server)
    # root /var/www/myapp/dist;
    # index index.html;

    # Reverse Proxy to Node.js App
    location / {
        proxy_pass http://localhost:5000; # The port Node.js/PM2 is running on

        # Pass real client IP and headers to Node.js
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # WebSocket Support (Crucial for Socket.io)
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";

        # Timeouts (adjust based on your app needs)
        proxy_connect_timeout 60s;
        proxy_read_timeout 60s;
        proxy_send_timeout 60s;
    }
}

# IMPORTANT: In your Express app, when behind a proxy, you MUST add:
# app.set('trust proxy', 1);
# Otherwise req.ip will always be 127.0.0.1 (the Nginx server) and rate limiting will block everyone!

