// ─── Operator Precedence ────────────────────────────────
// Higher precedence executes first (like math PEMDAS)
console.log(2 + 3 * 4);    // 14 (not 20) — * before +
console.log((2 + 3) * 4);  // 20 — parentheses override
console.log(2 ** 3 ** 2);  // 512 — ** is right-to-left: 3**2=9, 2**9=512

// Common precedence order (high to low):
// 1. () — grouping
// 2. ** — exponentiation
// 3. *, /, % — multiplicative
// 4. +, - — additive
// 5. <, >, <=, >= — relational
// 6. ==, ===, !=, !== — equality
// 7. && — logical AND
// 8. || — logical OR
// 9. ?? — nullish coalescing
// 10. ? : — ternary
// 11. =, +=, -= etc — assignment

