// ─── Deeply Nested (AVOID) ──────────────────────────────
function processOrderNested(user, cart, payment) {
  if (user) {
    if (user.isVerified) {
      if (cart && cart.length > 0) {
        if (payment && payment.isValid) {
          // Finally do the work — deeply buried!
          console.log('Processing order...');
          return { success: true };
        } else {
          return { error: 'Invalid payment' };
        }
      } else {
        return { error: 'Cart is empty' };
      }
    } else {
      return { error: 'User not verified' };
    }
  } else {
    return { error: 'User not found' };
  }
}

// ─── Guard Clauses (PREFERRED) ───────────────────────────
function processOrder(user, cart, payment) {
  // Each guard clause handles one failure condition
  if (!user)              return { error: 'User not found' };
  if (!user.isVerified)   return { error: 'User not verified' };
  if (!cart?.length)      return { error: 'Cart is empty' };
  if (!payment?.isValid)  return { error: 'Invalid payment' };

  // Happy path — flat and clear
  console.log('Processing order...');
  return { success: true };
}

// Usage
const result = processOrder(
  { isVerified: true },
  [{ id: 1, name: 'Book' }],
  { isValid: true }
);
