// ─── WeakSet ──────────────────────────────────────────────
// Only stores objects, holds weak references (allows GC)
const weakSet = new WeakSet();

let user1 = { name: 'Alice' };
let user2 = { name: 'Bob' };

weakSet.add(user1);
weakSet.add(user2);

console.log(weakSet.has(user1)); // true

// Use case: track which objects have been "processed"
const processedItems = new WeakSet();

function processItem(item) {
  if (processedItems.has(item)) {
    console.log('Already processed:', item.id);
    return;
  }
  // ... do processing ...
  processedItems.add(item);
  console.log('Processed:', item.id);
}

const item1 = { id: 1, data: 'something' };
processItem(item1); // Processed: 1
processItem(item1); // Already processed: 1

// WeakSet limitations:
// - No iteration (no forEach, no for...of)
// - No size property
// - Only .add(), .has(), .delete()

// ─── WeakMap ──────────────────────────────────────────────
// Keys must be objects, holds weak references to keys
const weakMap = new WeakMap();

let element = { tagName: 'div' }; // DOM element simulation
weakMap.set(element, { clickCount: 0, lastClicked: null });

function handleClick(el) {
  const data = weakMap.get(el);
  data.clickCount++;
  data.lastClicked = new Date();
  weakMap.set(el, data);
}

handleClick(element);
console.log(weakMap.get(element)); // { clickCount: 1, lastClicked: ... }

// ─── Private Data Pattern ────────────────────────────────
const _privateData = new WeakMap();

class BankAccount {
  constructor(owner, balance) {
    _privateData.set(this, { owner, balance, transactions: [] });
  }

  deposit(amount) {
    const data = _privateData.get(this);
    data.balance += amount;
    data.transactions.push({ type: 'deposit', amount });
  }

  getBalance() {
    return _privateData.get(this).balance;
  }
}

const account = new BankAccount('Alice', 1000);
account.deposit(500);
console.log(account.getBalance()); // 1500
