// ─── Custom Error Classes ────────────────────────────────
class AppError extends Error {
  constructor(message, statusCode = 500) {
    super(message);       // call parent Error constructor
    this.name = 'AppError';
    this.statusCode = statusCode;
    // Fix prototype chain (needed in TypeScript and some transpilers)
    Object.setPrototypeOf(this, AppError.prototype);
  }
}

class ValidationError extends AppError {
  constructor(field, message) {
    super(message, 400);
    this.name = 'ValidationError';
    this.field = field;
  }
}

class NotFoundError extends AppError {
  constructor(resource) {
    super(`${resource} not found`, 404);
    this.name = 'NotFoundError';
    this.resource = resource;
  }
}

// Using custom errors
function getUser(id) {
  if (typeof id !== 'number') {
    throw new ValidationError('id', 'User ID must be a number');
  }
  if (id <= 0) {
    throw new ValidationError('id', 'User ID must be positive');
  }
  const users = { 1: { name: 'Alice' }, 2: { name: 'Bob' } };
  if (!users[id]) {
    throw new NotFoundError('User');
  }
  return users[id];
}

function handleRequest(id) {
  try {
    const user = getUser(id);
    console.log('Found user:', user.name);
  } catch (err) {
    if (err instanceof NotFoundError) {
      console.error(`404: ${err.message}`);
    } else if (err instanceof ValidationError) {
      console.error(`400 (${err.field}): ${err.message}`);
    } else {
      console.error('500 Internal Error:', err.message);
      throw err; // re-throw unknown errors
    }
  }
}

handleRequest(1);        // Found user: Alice
handleRequest(99);       // 404: User not found
handleRequest('abc');    // 400 (id): User ID must be a number
handleRequest(-1);       // 400 (id): User ID must be positive

