  console.time('parallel');
  const [a, b, c] = await Promise.all([
    delay(1000, 'A'),
    delay(1000, 'B'),
    delay(1000, 'C'),
  ]);
  console.timeEnd('parallel'); // ~1000ms (all run simultaneously!)
  return [a, b, c];
}

