// ─── Async Generator (ES2018) ────────────────────────────
async function* paginate(baseUrl, totalPages) {
  for (let page = 1; page <= totalPages; page++) {
    // Simulate fetching each page
    const data = await new Promise(resolve =>
      setTimeout(() => resolve({ page, items: [`item${page}a`, `item${page}b`] }), 100)
    );
    yield data; // yield each page as it loads
  }
}

