// ─── Parallel with error isolation ───────────────────────
async function fetchSafely(url) {
  try {
    return { url, data: await fetch(url).then(r => r.json()) };
  } catch (err) {
    return { url, error: err.message };
  }
}

async function fetchMultiple(urls) {
  const results = await Promise.all(urls.map(fetchSafely));
  return {
    successful: results.filter(r => !r.error),
    failed: results.filter(r => r.error)
  };
}

// ─── Timeout wrapper ─────────────────────────────────────
async function withTimeout(promise, ms) {
  const timeout = new Promise((_, reject) =>
    setTimeout(() => reject(new Error(`Operation timed out after ${ms}ms`)), ms)
  );
  return Promise.race([promise, timeout]);
}

async function example() {
  try {
    const data = await withTimeout(
      fetch('https://api.example.com/data').then(r => r.json()),
      5000 // 5 second timeout
    );
    console.log(data);
  } catch (err) {
    console.error(err.message); // 'Operation timed out after 5000ms'
  }
}

// ─── Async queue / rate limiter ───────────────────────────
async function processInBatches(items, batchSize, processor) {
  const results = [];
  for (let i = 0; i < items.length; i += batchSize) {
    const batch = items.slice(i, i + batchSize);
    const batchResults = await Promise.all(batch.map(processor));
    results.push(...batchResults);
    console.log(`Processed batch ${Math.floor(i/batchSize) + 1}`);
  }
  return results;
}

