// ─── Aborting Requests (AbortController) ─────────────────
async function fetchWithTimeout(url, ms = 5000) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), ms);

  try {
    const res = await fetch(url, { signal: controller.signal });
    clearTimeout(timeoutId); // clear timer if request succeeds
    return await res.json();
  } catch (err) {
    if (err.name === 'AbortError') {
      throw new Error(`Request timed out after ${ms}ms`);
    }
    throw err;
  }
}

// Cancel on user action (like navigating away)
let currentController = null;

function startSearch(query) {
  if (currentController) {
    currentController.abort(); // cancel previous search
  }
  currentController = new AbortController();

  return fetch(`https://api.example.com/search?q=${query}`, {
    signal: currentController.signal
  }).then(r => r.json());
}

