// ─── Basic Class ─────────────────────────────────────────
class Animal {
  // Private fields (ES2022) — truly private!
  #name;
  #sound;

  // Public class field
  type = 'Animal'; // every instance gets this

  // Static property — belongs to the class, not instances
  static count = 0;

  constructor(name, sound) {
    this.#name = name;
    this.#sound = sound;
    Animal.count++;
  }

  // Getter — access like a property: animal.name
  get name() { return this.#name; }

  // Setter — intercept assignment: animal.name = 'Rex'
  set name(value) {
    if (typeof value !== 'string' || value.length < 1) {
      throw new Error('Name must be a non-empty string');
    }
    this.#name = value;
  }

  // Instance method
  speak() {
    return `${this.#name} says ${this.#sound}!`;
  }

  toString() {
    return `${this.type}: ${this.#name}`;
  }

  // Static method — called on Animal, not instance
  static describe() {
    return `Animals class — ${Animal.count} instances created`;
  }
}

