class Shape {
  #color;

  constructor(color = 'black') {
    this.#color = color;
  }

  get color() { return this.#color; }

  area() {
    throw new Error('area() must be implemented by subclass');
  }

  perimeter() {
    throw new Error('perimeter() must be implemented by subclass');
  }

  toString() {
    return `${this.constructor.name}: area=${this.area().toFixed(2)}, color=${this.#color}`;
  }
}

class Circle extends Shape {
  #radius;

  constructor(radius, color) {
    super(color); // MUST call super() before using 'this'!
    this.#radius = radius;
  }

  get radius() { return this.#radius; }

  area() { return Math.PI * this.#radius ** 2; }
  perimeter() { return 2 * Math.PI * this.#radius; }
}

class Rectangle extends Shape {
  #width; #height;

  constructor(width, height, color) {
    super(color);
    this.#width = width;
    this.#height = height;
  }

  area() { return this.#width * this.#height; }
  perimeter() { return 2 * (this.#width + this.#height); }

  // Override toString and call parent with super
  toString() {
    return `Rectangle(${this.#width}x${this.#height}) — ${super.toString()}`;
  }
}

class Square extends Rectangle {
  constructor(side, color) {
    super(side, side, color); // reuse Rectangle
  }
}

