// ─── Singleton Pattern ────────────────────────────────────
class Database {
  static #instance = null;
  #connectionString;
  #isConnected = false;

  constructor(connectionString) {
    if (Database.#instance) {
      return Database.#instance; // return existing instance
    }
    this.#connectionString = connectionString;
    Database.#instance = this;
  }

  connect() {
    this.#isConnected = true;
    console.log(`Connected to ${this.#connectionString}`);
  }

  static getInstance(connStr) {
    if (!Database.#instance) new Database(connStr);
    return Database.#instance;
  }
}

const db1 = new Database('mongodb://localhost:27017');
const db2 = new Database('other-url'); // returns SAME instance!
console.log(db1 === db2); // true — same instance

// ─── Observer Pattern ─────────────────────────────────────
class EventEmitter {
  #listeners = new Map();

  on(event, callback) {
    if (!this.#listeners.has(event)) {
      this.#listeners.set(event, []);
    }
    this.#listeners.get(event).push(callback);
    return () => this.off(event, callback); // return unsubscribe fn
  }

  off(event, callback) {
    const fns = this.#listeners.get(event);
    if (fns) this.#listeners.set(event, fns.filter(fn => fn !== callback));
  }

  emit(event, ...args) {
    const fns = this.#listeners.get(event) || [];
    fns.forEach(fn => fn(...args));
  }

  once(event, callback) {
    const wrapper = (...args) => {
      callback(...args);
      this.off(event, wrapper);
    };
    return this.on(event, wrapper);
  }
}

const emitter = new EventEmitter();

const unsubscribe = emitter.on('data', (payload) => {
  console.log('Received data:', payload);
});

emitter.once('connect', () => console.log('Connected! (runs only once)'));

emitter.emit('connect');        // 'Connected!'
emitter.emit('connect');        // nothing (once already fired)
emitter.emit('data', { id: 1, value: 'hello' }); // Received data: { id: 1, value: 'hello' }
unsubscribe(); // remove the listener
emitter.emit('data', { id: 2 }); // nothing (unsubscribed)

