// ─── Infinite Generator ───────────────────────────────────
function* naturals(start = 1) {
  let n = start;
  while (true) yield n++;
}

function take(n, gen) {
  const result = [];
  for (const val of gen) {
    result.push(val);
    if (result.length >= n) break;
  }
  return result;
}

console.log(take(5, naturals()));       // [1, 2, 3, 4, 5]
console.log(take(5, naturals(100)));    // [100, 101, 102, 103, 104]

// ─── Custom Iterable ─────────────────────────────────────
class Range {
  constructor(start, end, step = 1) {
    this.start = start;
    this.end = end;
    this.step = step;
  }

  // [Symbol.iterator] makes this class iterable!
  [Symbol.iterator]() {
    let current = this.start;
    const { end, step } = this;
    return {
      next() {
        if (current <= end) {
          const value = current;
          current += step;
          return { value, done: false };
        }
        return { value: undefined, done: true };
      }
    };
  }
}

const range = new Range(1, 10, 2);
console.log([...range]); // [1, 3, 5, 7, 9]

for (const n of new Range(0, 20, 5)) {
  console.log(n); // 0, 5, 10, 15, 20
}

// ─── Generator as Iterator shorthand ─────────────────────
class Range2 {
  constructor(start, end) {
    this.start = start;
    this.end = end;
  }

  *[Symbol.iterator]() { // generator method!
    for (let i = this.start; i <= this.end; i++) yield i;
  }
}

console.log([...new Range2(1, 5)]); // [1, 2, 3, 4, 5]

// ─── Basic Proxy ─────────────────────────────────────────
const target = { name: 'Alice', age: 30 };

const handler = {
  // Intercept property GET
  get(target, key, receiver) {
    console.log(`Getting: ${String(key)}`);
    return Reflect.get(target, key, receiver); // default behavior
  },

  // Intercept property SET
  set(target, key, value, receiver) {
    console.log(`Setting: ${String(key)} = ${value}`);

    // Validation
    if (key === 'age' && typeof value !== 'number') {
      throw new TypeError('Age must be a number');
    }
    return Reflect.set(target, key, value, receiver);
  },

  // Intercept 'in' operator
  has(target, key) {
    console.log(`Checking 'in': ${String(key)}`);
    return Reflect.has(target, key);
  },

  // Intercept delete
  deleteProperty(target, key) {
    console.log(`Deleting: ${String(key)}`);
    return Reflect.deleteProperty(target, key);
  }
};

const proxy = new Proxy(target, handler);
console.log(proxy.name);    // 'Getting: name' → 'Alice'
proxy.age = 31;             // 'Setting: age = 31'
// proxy.age = 'old';       // TypeError: Age must be a number
console.log('age' in proxy); // 'Checking 'in': age' → true

// ─── Reactive Object (Vue-like) ───────────────────────────
function reactive(obj, onChange) {
  return new Proxy(obj, {
    set(target, key, value) {
      const oldValue = target[key];
      const result = Reflect.set(target, key, value);
      if (oldValue !== value) {
        onChange(key, value, oldValue);
      }
      return result;
    }
  });
}

const state = reactive({ count: 0 }, (key, newVal, oldVal) => {
  console.log(`${key} changed: ${oldVal} → ${newVal}`);
  // In a real framework, this would trigger a re-render!
});

state.count = 1; // 'count changed: 0 → 1'
state.count = 2; // 'count changed: 1 → 2'

// ─── Read-only Proxy ──────────────────────────────────────
function readonly(obj) {
  return new Proxy(obj, {
    set(_, key) {
      throw new Error(`Cannot set property "${String(key)}" — object is read-only`);
    },
    deleteProperty(_, key) {
      throw new Error(`Cannot delete property "${String(key)}" — object is read-only`);
    }
  });
}

