// Format relative time (e.g., "2 hours ago")
function relativeTime(date) {
  const seconds = Math.floor((Date.now() - date.getTime()) / 1000);
  const rtf = new Intl.RelativeTimeFormat('en', { numeric: 'auto' });
  if (seconds < 60) return rtf.format(-seconds, 'second');
  if (seconds < 3600) return rtf.format(-Math.floor(seconds / 60), 'minute');
  if (seconds < 86400) return rtf.format(-Math.floor(seconds / 3600), 'hour');
  return rtf.format(-Math.floor(seconds / 86400), 'day');
}
console.log(relativeTime(new Date(Date.now() - 5 * 60 * 1000))); // '5 minutes ago'

// ─── Debounce — execute after idle period ─────────────────
// Useful for: search input, window resize, form validation
function debounce(fn, delay = 300) {
  let timer;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

// Only fires 300ms after user STOPS typing
const searchInput = document.querySelector('#search');
const handleSearch = debounce((e) => {
  console.log('Searching for:', e.target.value);
  // fetch results...
}, 300);
searchInput?.addEventListener('input', handleSearch);

// ─── Throttle — max once per period ──────────────────────
// Useful for: scroll events, mouse move, rate limiting API calls
function throttle(fn, limit = 100) {
  let lastRun = 0;
  return function(...args) {
    const now = Date.now();
    if (now - lastRun >= limit) {
      lastRun = now;
      return fn.apply(this, args);
    }
  };
}

// Fires at most once per 100ms during scroll
const handleScroll = throttle(() => {
  const scrollY = window.scrollY;
  // update UI based on scroll position
}, 100);
window.addEventListener('scroll', handleScroll);

// ─── Debounce with immediate option ─────────────────────
function debounceAdvanced(fn, delay, immediate = false) {
  let timer;
  return function(...args) {
    const callNow = immediate && !timer;
    clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      if (!immediate) fn.apply(this, args);
    }, delay);
    if (callNow) fn.apply(this, args);
  };
}

// ─── Memoization ─────────────────────────────────────────
function memoize(fn) {
  const cache = new Map();
  return function(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      console.log('Cache hit!');
      return cache.get(key);
    }
    const result = fn.apply(this, args);
    cache.set(key, result);
    return result;
  };
}

// Expensive computation — only calculated once per unique input
const expensiveCalc = memoize((n) => {
  console.log('Computing...');
  let result = 0;
  for (let i = 0; i < n; i++) result += i;
  return result;
});

console.log(expensiveCalc(1000000)); // Computing...
console.log(expensiveCalc(1000000)); // Cache hit!

// ─── Module Pattern ──────────────────────────────────────
// Encapsulate private state, expose clean public API
const CartModule = (() => {
  // Private state
  const _items = [];
  let _discount = 0;

  // Private method
  function _calculateTotal() {
    const subtotal = _items.reduce((sum, item) => sum + item.price * item.qty, 0);
    return subtotal * (1 - _discount);
  }

  // Public API
  return {
    addItem(item) {
      const existing = _items.find(i => i.id === item.id);
      if (existing) existing.qty += item.qty;
      else _items.push({ ...item, qty: item.qty || 1 });
    },
    removeItem(id) {
      const idx = _items.findIndex(i => i.id === id);
      if (idx > -1) _items.splice(idx, 1);
    },
    applyDiscount(pct) { _discount = pct / 100; },
    getTotal() { return _calculateTotal(); },
    getItems() { return [..._items]; }, // return copy
    clear() { _items.length = 0; }
  };
})();

CartModule.addItem({ id: 1, name: 'Book', price: 29.99 });
CartModule.addItem({ id: 2, name: 'Pen', price: 2.99, qty: 5 });
CartModule.applyDiscount(10); // 10% off
console.log('Total:', CartModule.getTotal().toFixed(2));

// ─── Factory Pattern ──────────────────────────────────────
function createUser(name, email, role = 'user') {
  const createdAt = new Date().toISOString();
  let _isActive = true;

  return {
    id: Math.random().toString(36).slice(2),
    name,
    email,
    role,
    createdAt,
    get isActive() { return _isActive; },
    deactivate() { _isActive = false; },
    toJSON() { return { name, email, role, createdAt, isActive: _isActive }; },
    toString() { return `${role.toUpperCase()}: ${name} <${email}>`; }
  };
}

