// ─── Strategy Pattern ─────────────────────────────────────
const sortStrategies = {
  bubble: (arr) => {
    const a = [...arr];
    for (let i = 0; i < a.length; i++)
      for (let j = 0; j < a.length - i - 1; j++)
        if (a[j] > a[j+1]) [a[j], a[j+1]] = [a[j+1], a[j]];
    return a;
  },
  quick: (arr) => {
    if (arr.length <= 1) return arr;
    const pivot = arr[arr.length - 1];
    const left = arr.slice(0, -1).filter(x => x <= pivot);
    const right = arr.slice(0, -1).filter(x => x > pivot);
    return [...sortStrategies.quick(left), pivot, ...sortStrategies.quick(right)];
  },
  native: (arr) => [...arr].sort((a, b) => a - b),
};

function sortArray(arr, strategy = 'native') {
  const fn = sortStrategies[strategy];
  if (!fn) throw new Error(`Unknown strategy: ${strategy}`);
  return fn(arr);
}

const data = [64, 34, 25, 12, 22, 11, 90];
console.log(sortArray(data, 'native')); // [11, 12, 22, 25, 34, 64, 90]
console.log(sortArray(data, 'quick'));  // same result

