// BAD: large function doing everything
// GOOD: small, focused functions
async function loginUser(credentials) {
  const user = await findUser(credentials.email);
  validatePassword(credentials.password, user.passwordHash);
  const token = generateToken(user.id);
  await logLoginEvent(user.id);
  return { user, token };
}

// ─── Error Boundary Pattern ───────────────────────────────
function withErrorHandling(fn, errorHandler = console.error) {
  return async (...args) => {
    try {
      return await fn(...args);
    } catch (err) {
      errorHandler(err);
      return null; // or throw, or return default value
    }
  };
}

const safeLoginUser = withErrorHandling(loginUser, (err) => {
  console.error('Login failed:', err.message);
  // track error, show notification, etc.
});
